"""Observe native blinker commands already generated by the vehicle interface."""
from openpilot.cereal import log
from opendbc.car.hyundai.values import HyundaiFlags
from opendbc.car.volkswagen.values import VolkswagenFlags
from openpilot.selfdrive.carrot.bluetooth.model import atomic_json
from openpilot.selfdrive.controls.lib.desire_lib.assistant_lane import ROOT, IDENTITY


def set_lane_change_blinkers(cc, meta):
  route = meta.assistantLaneSignalRoute
  native_voice = route == 'native' and meta.assistantLaneSignalId and cc.latActive
  if meta.laneChangeState != log.LaneChangeState.off and (route in ('', 'ordinary') or native_voice):
    if native_voice:
      cc.assistantLaneSignalId = meta.assistantLaneSignalId
    cc.leftBlinker = meta.laneChangeDirection == log.LaneChangeDirection.left
    cc.rightBlinker = meta.laneChangeDirection == log.LaneChangeDirection.right


def native_indicator(cp):
  if cp.passive:
    return None
  if cp.brand == 'volkswagen' and cp.flags & VolkswagenFlags.STOCK_EA_PRESENT:
    return 'EA_02'
  required = HyundaiFlags.CANFD | HyundaiFlags.CANFD_HDA2 | HyundaiFlags.ENABLE_BLINKERS
  if cp.brand == 'hyundai' and cp.flags & required == required:
    return 'SPAS2'
  return None


class NativeVoiceIndicator:
  def __init__(self, output, root=ROOT):
    self.output, self.root = output, root
    self.request, self.sent, self.dark = '', False, False
    self.last_report = self.last_update = 0.
    self.last_confirmed = False

  def update(self, now, cc, cs, car_state, frames):
    request = cc.assistantLaneSignalId
    if not request:
      self.request = ''
      return
    if request != self.request or not 0 <= now-self.last_update < .35:
      self.request, self.sent, self.dark, self.last_confirmed = request, False, False, False
    self.last_update = now
    left, right = cc.leftBlinker, cc.rightBlinker
    valid = cc.latActive and cs.canValid and left != right and IDENTITY.fullmatch(request)
    if self.output == 'EA_02':
      lamps = (car_state.left_blinker_active, car_state.right_blinker_active)
      address, length, byte, shift, value = 0x1F0, 8, 4, 0, 1 if left else 2
    else:
      lamps = (cs.leftBlinker, cs.rightBlinker)
      address, length, byte, shift, value = 0x16A, 32, 16, 5, 3 if left else 4
    # Only a frame already sent while the lamps were dark can confirm a later lamp edge.
    confirmed = bool(valid and self.sent and lamps == (left, right))
    if not valid or (lamps[1] if left else lamps[0]):
      self.sent = self.dark = False
    elif not any(lamps):
      self.dark = True
    if valid and self.dark and any(a == address and len(data) == length and (data[byte] >> shift) & 7 == value
                                   for a, data, _ in frames):
      self.sent = True
    if confirmed or self.last_confirmed:
      if confirmed != self.last_confirmed or now-self.last_report >= .1:
        try:
          atomic_json(self.root/'signal.json', {'route':'native', 'id':request, 'direction':'left' if left else 'right',
                                                'confirmed':confirmed, 'time':now})
        except OSError:
          pass  # Missing feedback must not interrupt the car loop or start a maneuver.
        self.last_report = now
    self.last_confirmed = confirmed
